def _t():

    class _SelfNS:
        pass
    self = _SelfNS()

    class aug_test:

        def __init__(self, value):
            self.val = value

        def __radd__(self, val):
            return self.val + val

        def __add__(self, val):
            return aug_test(self.val + val)

    class aug_test2(aug_test):

        def __iadd__(self, val):
            self.val = self.val + val
            return self

    class aug_test3(aug_test):

        def __iadd__(self, val):
            return aug_test3(self.val + val)

    class aug_test4(aug_test3):
        """Blocks inheritance, and fallback to __add__"""
        __iadd__ = None
    x = aug_test(1)
    y = x
    x += 10
    assert isinstance(x, aug_test), ('assertIsInstance', x, aug_test)
    assert y is not x, ('assertTrue', y is not x)
    assert x.val == 11, ('assertEqual', x.val, 11)
    x = aug_test2(2)
    y = x
    x += 10
    assert y is x, ('assertTrue', y is x)
    assert x.val == 12, ('assertEqual', x.val, 12)
    x = aug_test3(3)
    y = x
    x += 10
    assert isinstance(x, aug_test3), ('assertIsInstance', x, aug_test3)
    assert y is not x, ('assertTrue', y is not x)
    assert x.val == 13, ('assertEqual', x.val, 13)
    x = aug_test4(4)
    try:
        x += 10
    except TypeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
